CREATE OR REPLACE FUNCTION public.can_manage_membership(_id uuid,_type text,_permissions text[],_scopes uuid[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(public.organization_owner(_id,_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships actor WHERE actor.user_id=auth.uid() AND actor.organization_id=_id AND actor.organization_type=_type AND actor.status='ativo' AND 'subperfis'=ANY(actor.permissions) AND _permissions <@ actor.permissions AND (cardinality(actor.scope_ids)=0 OR (cardinality(_scopes)>0 AND _scopes <@ actor.scope_ids))),false) $$;
ALTER POLICY memberships_management_scope_guard ON public.organization_memberships USING(user_id=auth.uid() OR public.can_manage_membership(organization_id,organization_type,permissions,scope_ids));
REVOKE ALL ON FUNCTION public.can_manage_membership(uuid,text,text[],uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_manage_membership(uuid,text,text[],uuid[]) TO authenticated;